<?php
declare(strict_types=1); namespace App\Modules\Tourism\Models; use App\Core\Database;
final class TourismEvent{private Database $db;public function __construct(){$this->db=app()->get("db");}public function all(int $t,bool $d=false):array{$w=$d?"deleted_at IS NOT NULL":"deleted_at IS NULL";return $this->db->fetchAll("SELECT * FROM tourism_events WHERE tenant_id=? AND $w ORDER BY start_at ASC,id DESC",[$t]);}public function find(int $t,int $id,bool $d=false):?array{$w=$d?"deleted_at IS NOT NULL":"deleted_at IS NULL";return $this->db->fetch("SELECT * FROM tourism_events WHERE tenant_id=? AND id=? AND $w LIMIT 1",[$t,$id]);}public function save(int $t,int $id,array $d,int $u):int{if($id){$this->db->execute("UPDATE tourism_events SET provider_id=?,title=?,slug=?,description=?,event_type=?,start_at=?,end_at=?,venue=?,city=?,district=?,state=?,latitude=?,longitude=?,organizer_name=?,contact_phone=?,ticket_info=?,cover_image_path=?,status=?,featured=?,updated_by=? WHERE tenant_id=? AND id=? AND deleted_at IS NULL",[$d['provider_id'],$d['title'],$d['slug'],$d['description'],$d['event_type'],$d['start_at'],$d['end_at'],$d['venue'],$d['city'],$d['district'],$d['state'],$d['latitude'],$d['longitude'],$d['organizer_name'],$d['contact_phone'],$d['ticket_info'],$d['cover_image_path'],$d['status'],$d['featured'],$u,$t,$id]);return $id;} $this->db->execute("INSERT INTO tourism_events(uuid,tenant_id,provider_id,title,slug,description,event_type,start_at,end_at,venue,city,district,state,latitude,longitude,organizer_name,contact_phone,ticket_info,cover_image_path,status,featured,created_by,updated_by) VALUES(UUID(),?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",[$t,$d['provider_id'],$d['title'],$d['slug'],$d['description'],$d['event_type'],$d['start_at'],$d['end_at'],$d['venue'],$d['city'],$d['district'],$d['state'],$d['latitude'],$d['longitude'],$d['organizer_name'],$d['contact_phone'],$d['ticket_info'],$d['cover_image_path'],$d['status'],$d['featured'],$u,$u]);return(int)$this->db->lastInsertId();}public function delete(int $t,int $id,int $u):void{$this->db->execute("UPDATE tourism_events SET deleted_at=NOW(),updated_by=? WHERE tenant_id=? AND id=?",[$u,$t,$id]);}public function restore(int $t,int $id,int $u):void{$this->db->execute("UPDATE tourism_events SET deleted_at=NULL,updated_by=? WHERE tenant_id=? AND id=?",[$u,$t,$id]);}public function slugExists(int $t,string $s,?int $id=null):bool{$q="SELECT id FROM tourism_events WHERE tenant_id=? AND slug=? AND deleted_at IS NULL";$p=[$t,$s];if($id){$q.=" AND id<>?";$p[]=$id;}return $this->db->fetch($q." LIMIT 1",$p)!==null;}}
